<?php
require dirname(__DIR__).'/app/bootstrap.php';$token=(string)($_GET['token']??'');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(!preg_match('/^[a-f0-9]{64}$/D',$token))throw new DomainException('Reset link is invalid or expired.');$password=required_text('password',200);if(strlen($password)<12)throw new DomainException('Use at least 12 characters.');if($password!==($_POST['confirm_password']??''))throw new DomainException('Passwords do not match.');transaction(function()use($token,$password){$reset=one('SELECT r.*,u.business_id FROM password_resets r JOIN users u ON u.id=r.user_id AND u.active=1 WHERE r.token_hash=? AND r.used_at IS NULL AND r.expires_at>NOW() FOR UPDATE',[hash('sha256',$token)]);if(!$reset)throw new DomainException('Reset link is invalid or expired.');query('UPDATE users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$reset['user_id']]);query('UPDATE password_resets SET used_at=NOW() WHERE id=?',[$reset['id']]);query("INSERT INTO activity_logs(business_id,user_id,action,entity,entity_id,details) VALUES(?,?,'password.reset','user',?,'{}')",[$reset['business_id'],$reset['user_id'],$reset['user_id']]);});$_SESSION=[];session_regenerate_id(true);flash('Your password was reset. Sign in with your new password.');redirect('login.php');}catch(DomainException $ex){$error=$ex->getMessage();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset password · YBT</title><link rel="stylesheet" href="assets/css/app.css"></head><body><main><section class="panel form-panel"><h1>Set a new password</h1><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><form method="post"><?php csrf_field(); ?><label class="field"><span>New password (12+ characters)</span><input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label class="field"><span>Confirm new password</span><input name="confirm_password" type="password" minlength="12" required autocomplete="new-password"></label><div class="form-actions"><button class="btn primary">Reset password</button></div></form></section></main></body></html>
